fn main() {
    let grid = vec(4, 9, 2, 3, 5, 7, 8, 1, 6)
    for i in range(0, 3) {
        print(sum(subvec(grid, i * 3, (i + 1) * 3)))
    }
    for i in range(0, 3) {
        let mut sum = 0
        for j in range(0, 3) {
            sum += grid[j * 3 + i]
        }
        print(sum)
    }
    let mut diag1_sum = 0
    let mut diag2_sum = 0
    for i in range(0, 3) {
        diag1_sum += grid[i * 3 + i]
        diag2_sum += grid[i * 3 + (2 - i)]
    }
    print(diag1_sum)
    print(diag2_sum)
    let all_equal = diag1_sum == diag2_sum
    for i in range(0, 3) {
        all_equal = all_equal && sum(subvec(grid, i * 3, (i + 1) * 3)) == diag1_sum
        all_equal = all_equal && {
            let mut col_sum = 0
            for j in range(0, 3) {
                col_sum += grid[j * 3 + i]
            }
            col_sum == diag1_sum
        }
    }
    print(all_equal)
}

