        Rect { width: 7, height: 4 },
        Square { side: 5 },
        Circle { radius: 3 },
        Rect { width: 2, height: 9 }
    )
    let mut total_area = 0
    let mut max_area = 0
    let mut max_kind = ""
    for f in figures {
        match f {
            Rect { width, height } => {
                print_str("rect")
                let a = area(Rect { width, height })
                print(a)
                total_area += a
                if a > max_area {
                    max_area = a
                    max_kind = "rect"
                }
            },
            Square { side } => {
                print_str("square")
                let a = area(Square { side })
                print(a)
                total_area += a
                if a > max_area {
                    max_area = a
                    max_kind = "square"
                }
            },
            Circle { radius } => {
                print_str("circle")
                let a = area(Circle { radius })
                print(a)
                total_area += a
                if a > max_area {
                    max_area = a
                    max_kind = "circle"
                }
            }
        }
    }
    print(total_area)
    print_str(max_kind)
}

